export interface VerbEntry {
  word: string           // base verb
  v1: string             // present form (go/goes)
  v2: string             // simple past (went)
  v3: string             // past participle (gone)
  meaning_hindi: string
  pronunciation: string
  hindi_pronunciation: string
  example: string
  example_hindi: string
  verb_sentence_english: string  // V2 in a sentence
  verb_sentence_hindi: string    // V2 Hindi equivalent
  memory_trick: string
  level: 'A0' | 'A1' | 'A2' | 'B1' | 'B2'
  category: 'irregular' | 'regular' | 'business' | 'freelance' | 'interview'
  same_all_forms?: boolean // put/cut/hit
}

