// Helper: get verbs by category
export const getVerbsByCategory = (category: VerbEntry['category']) =>
  VERBS.filter(v => v.category === category)

// Helper: get verbs by level
export const getVerbsByLevel = (level: VerbEntry['level']) =>
  VERBS.filter(v => v.level === level)

// Helper: get daily session (10 unseen verbs)
export const getDailyVerbs = (seenWords: Set<string>, level: string, count = 10): VerbEntry[] => {
  const levelOrder = ['A0', 'A1', 'A2', 'B1', 'B2']
  const levelIdx = levelOrder.indexOf(level)
  const eligibleLevels = levelOrder.slice(0, levelIdx + 1)
  
  const unseen = VERBS
    .filter(v => eligibleLevels.includes(v.level) && !seenWords.has(v.word))
    .sort((a, b) => levelOrder.indexOf(a.level) - levelOrder.indexOf(b.level))
  
  if (unseen.length >= count) return unseen.slice(0, count)
  
  // Fallback: add from all levels
  const extras = VERBS.filter(v => !seenWords.has(v.word))
  return [...new Set([...unseen, ...extras])].slice(0, count)
}
